local function _decode(encoded, index)
    local acc, bits, count, out = 0, 0, 0, {}
    for pos=1,#encoded do
        local ch = encoded:byte(pos)
        if ch == 61 then break end
        local val = _lookup[ch]
        if val ~= nil then
            acc = acc*64+val
            bits = bits+6
